export const csvToJsonByKey = (csvString, key) => {
  const lines = csvString.trim().split("\n");
  const headers = lines[0].split(",");
  const result = {};
  for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(",");
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      const value = currentLine[j];
      obj[headers[j]] = isNaN(value) ? value : Number(value);
    }
    const countyFips = currentLine[headers.indexOf(key)];
    result[countyFips] = obj;
  }
  return result;
};

export const csvToJsonArray = (csvString) => {
    const lines = csvString.trim().split("\n");
    const headers = lines[0].split(",").map(header => header.trim());
    
    const result = [];
    
    for (let i = 1; i < lines.length; i++) {
      const currentLine = lines[i].split(",").map(item => item.trim());
      const obj = {};
      for (let j = 0; j < headers.length; j++) {
        const value = currentLine[j];
        obj[headers[j]] = isNaN(value) ? value : Number(value);
      }
      result.push(obj);
    }
    return result;
  };